            return info

    @synchronized
    def close(self):
        if self._closed:
            return
        if self.conn is not None:
            self.conn.close()
            self.conn = None
        if self._lock_fd is not None:
            # Closing this retained descriptor releases its original flock.
            # Keep it available if the close itself has not completed.
            os.close(self._lock_fd)
            self._lock_fd = None
        self._closed = True

